  `customer_name` varchar(255) NOT NULL,
  `payment_method` varchar(50) NOT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`items`)),
  `total_amount` decimal(10,2) NOT NULL,
  `validation_status` varchar(50) DEFAULT 'Pending Validation',
  `shift_status` varchar(50) DEFAULT 'no_active_shift',
  `validated_by` int(11) DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `validation_remarks` text DEFAULT NULL,
  `adjustments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`adjustments`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Triggers `pending_merchandise_transactions`
--
DELIMITER $$
CREATE TRIGGER `log_validation_action` AFTER UPDATE ON `pending_merchandise_transactions` FOR EACH ROW BEGIN
    IF NEW.validation_status != 'Pending Validation' AND OLD.validation_status = 'Pending Validation' THEN
            transaction_id,
            pending_transaction_id,
            action,
            manager_id,
            manager_name,
            staff_id,
            staff_name,
            station_id,
            original_total,
            adjusted_total,
            remarks,
            original_items,
            adjusted_items,
            ip_address,
            user_agent
        )
        VALUES (
            NEW.transaction_id,
            NEW.id,
            CASE NEW.validation_status
                WHEN 'Approved' THEN 'approve'
                WHEN 'Rejected' THEN 'reject'
                WHEN 'Adjusted' THEN 'adjust'
                ELSE 'unknown'
            END,
            NEW.validated_by,
            (SELECT name FROM users WHERE id = NEW.validated_by),
            NEW.staff_id,
            (SELECT name FROM users WHERE id = NEW.staff_id),
            NEW.station_id,
            OLD.total_amount,
            NEW.total_amount,
            NEW.validation_remarks,
            OLD.items,
            NEW.adjustments,
            NULL,
            NULL
        );
    END IF;
END
$$
DELIMITER ;

