CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `fuel_stations`  AS SELECT `fp`.`id` AS `id`, `fp`.`station_id` AS `station_id`, `fp`.`pump_number` AS `pump_number`, `ft`.`name` AS `fuel_type`, `fp`.`capacity` AS `capacity`, `fp`.`status` AS `status`, `fp`.`created_at` AS `created_at` FROM (`fuel_pumps` `fp` left join `fuel_types` `ft` on(`fp`.`fuel_type_id` = `ft`.`id`)) ;

