--
-- Structure for view `pending_transactions_view`
--
DROP TABLE IF EXISTS `pending_transactions_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `pending_transactions_view` AS SELECT `pmt`.`id` AS `id`, `pmt`.`transaction_id` AS `transaction_id`, `pmt`.`station_id` AS `station_id`, `s`.`name` AS `station_name`, `pmt`.`staff_id` AS `staff_id`, CONCAT(`u`.`first_name`, ' ', `u`.`last_name`) AS `staff_name`, `pmt`.`shift_id` AS `shift_id`, `sh`.`start_time` AS `start_time`, `pmt`.`customer_name` AS `customer_name`, `pmt`.`payment_method` AS `payment_method`, `pmt`.`items` AS `items`, `pmt`.`total_amount` AS `total_amount`, `pmt`.`validation_status` AS `validation_status`, `pmt`.`shift_status` AS `shift_status`, `pmt`.`created_at` AS `created_at`, `pmt`.`validated_by` AS `validated_by`, CONCAT(`v_u`.`first_name`, ' ', `v_u`.`last_name`) AS `validated_by_name`, `pmt`.`validated_at` AS `validated_at`, `pmt`.`validation_remarks` AS `validation_remarks`, `pmt`.`adjustments` AS `adjustments`, CASE WHEN `pmt`.`validation_status` = 'Pending Validation' THEN 'warning' WHEN `pmt`.`validation_status` = 'Approved' THEN 'success' WHEN `pmt`.`validation_status` = 'Rejected' THEN 'danger' WHEN `pmt`.`validation_status` = 'Adjusted' THEN 'info' ELSE 'secondary' END AS `status_badge_class` FROM ((((`pending_merchandise_transactions` `pmt` left join `stations` `s` on(`pmt`.`station_id` = `s`.`id`)) left join `users` `u` on(`pmt`.`staff_id` = `u`.`user_id`)) left join `users` `v_u` on(`pmt`.`validated_by` = `v_u`.`user_id`)) left join `shifts` `sh` on(`pmt`.`shift_id` = `sh`.`id`)) ;

