CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `staff_calendar_dashboard`  AS SELECT `staff_calendar_events`.`station_id` AS `station_id`, count(case when `staff_calendar_events`.`event_date` = curdate() then 1 end) AS `today_events`, count(case when `staff_calendar_events`.`event_date` between curdate() and curdate() + interval 3 day then 1 end) AS `upcoming_3days`, count(case when `staff_calendar_events`.`status` = 'pending' then 1 end) AS `pending_count`, count(case when `staff_calendar_events`.`status` = 'approved' then 1 end) AS `approved_count`, count(case when `staff_calendar_events`.`status` = 'completed' then 1 end) AS `completed_count`, count(case when `staff_calendar_events`.`status` = 'cancelled' then 1 end) AS `cancelled_count`, count(0) AS `total_events` FROM `staff_calendar_events` WHERE `staff_calendar_events`.`event_date` >= curdate() - interval 7 day GROUP BY `staff_calendar_events`.`station_id` ;

